=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md per microarchitecture.md (explicit count
// register, pointers wrapped at DEPTH-1, flag-gated requests, synchronous
// active-low reset of pointers and count; storage is not reset).
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer AW       = $clog2(DEPTH);
    localparam integer CW       = $clog2(DEPTH + 1);
    localparam integer ONE      = 1;
    localparam integer DEPTH_M1 = DEPTH - 1;
    localparam [AW-1:0] LAST_PTR = DEPTH_M1[AW-1:0];
    localparam [AW-1:0] PTR_ONE  = ONE[AW-1:0];
    localparam [AW-1:0] PTR_ZERO = {AW{1'b0}};
    localparam [CW-1:0] FULL_CNT = DEPTH[CW-1:0];
    localparam [CW-1:0] CNT_ONE  = ONE[CW-1:0];
    localparam [CW-1:0] CNT_ZERO = {CW{1'b0}};

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [AW-1:0] wr_ptr_q;
    reg [AW-1:0] wr_ptr_d;
    reg [AW-1:0] rd_ptr_q;
    reg [AW-1:0] rd_ptr_d;
    reg [CW-1:0] cnt_q;
    reg [CW-1:0] cnt_d;

    wire wr_acc;
    wire rd_acc;

    // Flags are compares on a register: no combinational input dependence.
    assign full    = (cnt_q == FULL_CNT);
    assign empty   = (cnt_q == CNT_ZERO);
    assign count   = cnt_q;

    // Overflow and underflow policy: the flags gate the requests.
    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;

    // First-word fall-through: combinational read of the oldest slot.
    assign rd_data = mem[rd_ptr_q];

    always @(*) begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST_PTR) begin
                wr_ptr_d = PTR_ZERO;
            end else begin
                wr_ptr_d = wr_ptr_q + PTR_ONE;
            end
        end
    end

    always @(*) begin
        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_ptr_q == LAST_PTR) begin
                rd_ptr_d = PTR_ZERO;
            end else begin
                rd_ptr_d = rd_ptr_q + PTR_ONE;
            end
        end
    end

    always @(*) begin
        cnt_d = cnt_q;
        if (wr_acc && !rd_acc) begin
            cnt_d = cnt_q + CNT_ONE;
        end else if (!wr_acc && rd_acc) begin
            cnt_d = cnt_q - CNT_ONE;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= PTR_ZERO;
            rd_ptr_q <= PTR_ZERO;
            cnt_q    <= CNT_ZERO;
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            cnt_q    <= cnt_d;
        end
    end

    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    // Solver-chosen slot.
    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*) assume (f_addr <= LAST_PTR);

    wire [31:0] f_sum    = rd_ptr_q + cnt_q;
    wire [31:0] f_wr_exp = (f_sum >= DEPTH) ? (f_sum - DEPTH) : f_sum;
    wire [31:0] f_off    = (f_addr >= rd_ptr_q) ? (f_addr - rd_ptr_q)
                                                : (f_addr + DEPTH - rd_ptr_q);
    wire        f_valid  = (f_off < cnt_q);

    reg [WIDTH-1:0] f_data;
    always @(posedge clk) begin
        if (rst_n && wr_acc && (wr_ptr_q == f_addr)) f_data <= wr_data;
    end

    // State invariants.
    always @(*) begin
        if (f_past_valid) begin
            assert (cnt_q <= DEPTH);
            assert (wr_ptr_q <= LAST_PTR);
            assert (rd_ptr_q <= LAST_PTR);
            assert (full == (cnt_q == DEPTH));
            assert (empty == (cnt_q == 0));
            assert (!(full && empty));
            assert (wr_ptr_q == f_wr_exp);
            if (f_valid) begin
                assert (mem[f_addr] == f_data);
                if (rd_ptr_q == f_addr) assert (rd_data == f_data);
            end
        end
    end

    // Transition properties.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if ($past(!rst_n)) begin
                assert (cnt_q == 0);
                assert (wr_ptr_q == 0);
                assert (rd_ptr_q == 0);
                assert (empty);
                assert (!full);
            end else begin
                if ($past(wr_acc) && !$past(rd_acc)) begin
                    assert (cnt_q == $past(cnt_q) + CNT_ONE);
                end else if (!$past(wr_acc) && $past(rd_acc)) begin
                    assert (cnt_q == $past(cnt_q) - CNT_ONE);
                end else begin
                    assert (cnt_q == $past(cnt_q));
                end
                if ($past(full)) assert (wr_ptr_q == $past(wr_ptr_q));
                if ($past(empty)) assert (rd_ptr_q == $past(rd_ptr_q));
                if ($past(wr_en && full && !rd_en)) assert (cnt_q == $past(cnt_q));
                if ($past(rd_en && empty && !wr_en)) assert (cnt_q == $past(cnt_q));
            end
        end
    end

    // Covers: the proof is not vacuous.
    reg f_seen_full;
    always @(posedge clk) begin
        if (!rst_n) f_seen_full <= 1'b0;
        else if (full) f_seen_full <= 1'b1;
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover (full);
            cover (f_seen_full && empty);
            cover (wr_acc && rd_acc && !full);
            cover (wr_acc && (wr_ptr_q == LAST_PTR));
            cover (rd_acc && f_valid && (rd_ptr_q == f_addr));
        end
    end
`endif

endmodule
=== END FILE ===
