// Self-checking testbench for sync_fifo: two configurations on the same
// stimulus, each checked every rising edge against a reference queue.

`define SF_GOAL(HITS, NAME) \
    if ((HITS) == 32'd0) begin \
        failed = failed + 32'd1; \
        $error("sync_fifo D%0d W%0d: coverage goal not reached: %s", DEPTH, WIDTH, NAME); \
    end else begin \
        passed = passed + 32'd1; \
    end

module sync_fifo_harness #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             wr_en,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    input  wire             finish_check,
    output wire [31:0]      passed_o,
    output wire [31:0]      failed_o
);
    localparam integer AW       = $clog2(DEPTH);
    localparam integer CW       = $clog2(DEPTH + 1);
    localparam integer ONE      = 1;
    localparam integer DEPTH_M1 = DEPTH - 1;
    localparam [AW-1:0] LAST_PTR = DEPTH_M1[AW-1:0];
    localparam [AW-1:0] PTR_ONE  = ONE[AW-1:0];
    localparam [CW-1:0] FULL_CNT = DEPTH[CW-1:0];
    localparam [CW-1:0] CNT_ONE  = ONE[CW-1:0];
    localparam [CW-1:0] CNT_ZERO = {CW{1'b0}};

    wire             full;
    wire             empty;
    wire [WIDTH-1:0] rd_data;
    wire [CW-1:0]    count;

    sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full),
        .rd_en   (rd_en),
        .rd_data (rd_data),
        .empty   (empty),
        .count   (count)
    );

    reg [WIDTH-1:0] m_q [0:DEPTH-1];
    reg [AW-1:0]    m_head;
    reg [AW-1:0]    m_tail;
    reg [CW-1:0]    m_count;
    reg             m_init;
    reg             m_seen_full;
    reg             m_done;
    reg             m_wr;
    reg             m_rd;
    reg [31:0]      passed;
    reg [31:0]      failed;
    reg [31:0]      c_full;
    reg [31:0]      c_wr_full;
    reg [31:0]      c_drain;
    reg [31:0]      c_rd_empty;
    reg [31:0]      c_both_empty;
    reg [31:0]      c_both_full;
    reg [31:0]      c_both_mid;
    reg [31:0]      c_wr_wrap;
    reg [31:0]      c_rd_wrap;
    reg [31:0]      c_rst_traffic;

    assign passed_o = passed;
    assign failed_o = failed;

    initial begin
        passed        = 32'd0;
        failed        = 32'd0;
        c_full        = 32'd0;
        c_wr_full     = 32'd0;
        c_drain       = 32'd0;
        c_rd_empty    = 32'd0;
        c_both_empty  = 32'd0;
        c_both_full   = 32'd0;
        c_both_mid    = 32'd0;
        c_wr_wrap     = 32'd0;
        c_rd_wrap     = 32'd0;
        c_rst_traffic = 32'd0;
        m_init        = 1'b0;
        m_seen_full   = 1'b0;
        m_done        = 1'b0;
        m_wr          = 1'b0;
        m_rd          = 1'b0;
        m_head        = {AW{1'b0}};
        m_tail        = {AW{1'b0}};
        m_count       = {CW{1'b0}};
    end

    always @(posedge clk) begin
        // Check the outputs, which show the state after the previous edge.
        if (m_init) begin
            if (count !== m_count) begin
                failed = failed + 32'd1;
                $error("sync_fifo D%0d W%0d: count is %0d, expected %0d", DEPTH, WIDTH, count, m_count);
            end else begin
                passed = passed + 32'd1;
            end
            if (full !== (m_count == FULL_CNT)) begin
                failed = failed + 32'd1;
                $error("sync_fifo D%0d W%0d: full is %b with count %0d", DEPTH, WIDTH, full, m_count);
            end else begin
                passed = passed + 32'd1;
            end
            if (empty !== (m_count == CNT_ZERO)) begin
                failed = failed + 32'd1;
                $error("sync_fifo D%0d W%0d: empty is %b with count %0d", DEPTH, WIDTH, empty, m_count);
            end else begin
                passed = passed + 32'd1;
            end
            if (m_count != CNT_ZERO) begin
                if (rd_data !== m_q[m_head]) begin
                    failed = failed + 32'd1;
                    $error("sync_fifo D%0d W%0d: rd_data is %0h, expected %0h", DEPTH, WIDTH, rd_data, m_q[m_head]);
                end else begin
                    passed = passed + 32'd1;
                end
            end
        end

        // Reference queue update for this edge.
        if (!rst_n) begin
            if (m_init && (m_count != CNT_ZERO)) c_rst_traffic = c_rst_traffic + 32'd1;
            m_head  = {AW{1'b0}};
            m_tail  = {AW{1'b0}};
            m_count = CNT_ZERO;
            m_init  = 1'b1;
        end else if (m_init) begin
            m_wr = wr_en && (m_count != FULL_CNT);
            m_rd = rd_en && (m_count != CNT_ZERO);
            if (m_count == FULL_CNT) begin
                c_full      = c_full + 32'd1;
                m_seen_full = 1'b1;
            end
            if (wr_en && (m_count == FULL_CNT)) c_wr_full = c_wr_full + 32'd1;
            if (m_seen_full && (m_count == CNT_ZERO)) c_drain = c_drain + 32'd1;
            if (rd_en && (m_count == CNT_ZERO)) c_rd_empty = c_rd_empty + 32'd1;
            if (wr_en && rd_en && (m_count == CNT_ZERO)) c_both_empty = c_both_empty + 32'd1;
            if (wr_en && rd_en && (m_count == FULL_CNT)) c_both_full = c_both_full + 32'd1;
            if (wr_en && rd_en && (m_count != CNT_ZERO) && (m_count != FULL_CNT)) c_both_mid = c_both_mid + 32'd1;
            if (m_wr && (m_tail == LAST_PTR)) c_wr_wrap = c_wr_wrap + 32'd1;
            if (m_rd && (m_head == LAST_PTR)) c_rd_wrap = c_rd_wrap + 32'd1;
            if (m_rd) begin
                m_head = (m_head == LAST_PTR) ? {AW{1'b0}} : (m_head + PTR_ONE);
            end
            if (m_wr) begin
                m_q[m_tail] = wr_data;
                m_tail = (m_tail == LAST_PTR) ? {AW{1'b0}} : (m_tail + PTR_ONE);
            end
            if (m_wr && !m_rd) begin
                m_count = m_count + CNT_ONE;
            end else if (!m_wr && m_rd) begin
                m_count = m_count - CNT_ONE;
            end
        end

        // Coverage goals, evaluated once at the end of the run.
        if (finish_check && !m_done) begin
            m_done = 1'b1;
            `SF_GOAL(c_full, "filled to full")
            `SF_GOAL(c_wr_full, "write while full")
            `SF_GOAL(c_drain, "drained to empty after full")
            `SF_GOAL(c_rd_empty, "read while empty")
            `SF_GOAL(c_both_empty, "write and read together when empty")
            `SF_GOAL(c_both_full, "write and read together when full")
            `SF_GOAL(c_both_mid, "write and read together in between")
            `SF_GOAL(c_wr_wrap, "write pointer wrap-around")
            `SF_GOAL(c_rd_wrap, "read pointer wrap-around")
            `SF_GOAL(c_rst_traffic, "reset during traffic")
        end
    end
endmodule

module sync_fifo_tb;
    reg             clk;
    reg             rst_n;
    reg             wr_en;
    reg             rd_en;
    reg             finish_check;
    reg  [11:0]     wdata;
    reg  [31:0]     lfsr;
    reg  [8*64-1:0] nonce;
    reg  [31:0]     passed;
    reg  [31:0]     failed;
    wire [31:0]     passed_d8;
    wire [31:0]     failed_d8;
    wire [31:0]     passed_d5;
    wire [31:0]     failed_d5;
    integer         seg;

    sync_fifo_harness #(.DEPTH(8), .WIDTH(8)) h_d8 (
        .clk          (clk),
        .rst_n        (rst_n),
        .wr_en        (wr_en),
        .wr_data      (wdata[7:0]),
        .rd_en        (rd_en),
        .finish_check (finish_check),
        .passed_o     (passed_d8),
        .failed_o     (failed_d8)
    );

    sync_fifo_harness #(.DEPTH(5), .WIDTH(12)) h_d5 (
        .clk          (clk),
        .rst_n        (rst_n),
        .wr_en        (wr_en),
        .wr_data      (wdata),
        .rd_en        (rd_en),
        .finish_check (finish_check),
        .passed_o     (passed_d5),
        .failed_o     (failed_d5)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    function [31:0] xorshift(input [31:0] x);
        reg [31:0] y;
        begin
            y = x ^ (x << 13);
            y = y ^ (y >> 17);
            y = y ^ (y << 5);
            xorshift = y;
        end
    endfunction

    // Apply one cycle of stimulus at the falling edge.
    task drive(input r_n, input w, input r);
        begin
            @(negedge clk);
            lfsr  = xorshift(lfsr);
            rst_n = r_n;
            wr_en = w;
            rd_en = r;
            wdata = lfsr[11:0];
        end
    endtask

    task drive_rand(input [7:0] wthr, input [7:0] rthr);
        begin
            @(negedge clk);
            lfsr  = xorshift(lfsr);
            rst_n = 1'b1;
            wr_en = (lfsr[31:24] < wthr);
            rd_en = (lfsr[23:16] < rthr);
            wdata = lfsr[11:0];
        end
    endtask

    initial begin
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        rst_n        = 1'b0;
        wr_en        = 1'b0;
        rd_en        = 1'b0;
        wdata        = 12'd0;
        finish_check = 1'b0;
        lfsr         = 32'h2545_F491;
        passed       = 32'd0;
        failed       = 32'd0;

        // Reset.
        repeat (3) drive(1'b0, 1'b0, 1'b0);
        // Read while empty.
        repeat (2) drive(1'b1, 1'b0, 1'b1);
        // Write and read together when empty: only the write is accepted.
        drive(1'b1, 1'b1, 1'b1);
        // Fill to full, then write while full.
        repeat (10) drive(1'b1, 1'b1, 1'b0);
        // Write and read together when full: only the read is accepted.
        drive(1'b1, 1'b1, 1'b1);
        // Write and read together in between.
        repeat (3) drive(1'b1, 1'b1, 1'b1);
        // Drain to empty, then read while empty.
        repeat (12) drive(1'b1, 1'b0, 1'b1);
        // Together when empty again, then build some occupancy.
        drive(1'b1, 1'b1, 1'b1);
        repeat (3) drive(1'b1, 1'b1, 1'b0);
        // Reset during traffic, with requests active (they are ignored).
        repeat (2) drive(1'b0, 1'b1, 1'b1);
        repeat (2) drive(1'b1, 1'b0, 1'b1);

        // Random traffic: write-heavy, read-heavy and balanced segments.
        for (seg = 0; seg < 12; seg = seg + 1) begin
            if ((seg % 3) == 0) begin
                repeat (150) drive_rand(8'd200, 8'd70);
            end else if ((seg % 3) == 1) begin
                repeat (150) drive_rand(8'd70, 8'd200);
            end else begin
                repeat (150) drive_rand(8'd128, 8'd128);
            end
            if (seg == 3) begin
                repeat (2) drive(1'b0, 1'b1, 1'b1);
            end
        end

        repeat (2) drive(1'b1, 1'b0, 1'b0);
        @(negedge clk);
        finish_check = 1'b1;
        @(negedge clk);
        @(negedge clk);
        passed = passed_d8 + passed_d5;
        failed = failed_d8 + failed_d5;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

